package server

import (
	"encoding/json"
	"errors"
	"io"
	"mime"
	"net/http"
	"strconv"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// maxChunkBytes caps a single inbound chunk body.
const maxChunkBytes = 64 << 20

type attachmentRequest struct {
	ID         string          `json:"attachmentId"`
	TotalBytes json.RawMessage `json:"totalBytes"`
	ChunkSize  json.RawMessage `json:"chunkSize"`
	SHA256     string          `json:"sha256"`
}

// attachmentListEntry is one item of the attachment listing response.
type attachmentListEntry struct {
	ID             string  `json:"attachmentId"`
	TotalBytes     int64   `json:"totalBytes"`
	ChunkSize      int64   `json:"chunkSize"`
	SHA256         string  `json:"sha256"`
	Complete       bool    `json:"complete"`
	Owned          bool    `json:"owned"`
	ReceivedChunks []int64 `json:"receivedChunks"`
}

// handleListAttachments is the read-only listing over the attachment
// collection: every upload the device in the path created plus every upload
// another device created and granted it read access to, each at most once,
// ordered by creation ascending. limit (1..1000, default 100) and offset
// (non-negative, default 0) page the result; an illegal value is a 400 JSON
// error checked before the device lookup. An unregistered device is a 404
// JSON error with no listing. The handler writes nothing: no attachment,
// chunk or access state changes.
func handleListAttachments(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty

	limit, offset, ok := parseAttachmentListQuery(w, r)
	if !ok {
		return
	}

	items, err := s.ListAttachments(deviceID, limit, offset)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		default:
			writeError(w, http.StatusInternalServerError, "failed to list attachments")
		}
		return
	}

	entries := make([]attachmentListEntry, 0, len(items))
	for _, item := range items {
		entries = append(entries, attachmentListEntry{
			ID:             item.ID,
			TotalBytes:     item.TotalBytes,
			ChunkSize:      item.ChunkSize,
			SHA256:         item.SHA256,
			Complete:       item.Complete,
			Owned:          item.Owned,
			ReceivedChunks: item.ReceivedChunks,
		})
	}

	writeJSON(w, http.StatusOK, map[string]any{"attachments": entries})
}

// parseAttachmentListQuery parses the limit/offset pagination parameters of
// the attachment listing, writing the documented 400 on an illegal value.
func parseAttachmentListQuery(w http.ResponseWriter, r *http.Request) (limit, offset int64, ok bool) {
	q := r.URL.Query()

	limit = defaultListLimit
	if raw := q.Get("limit"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 1 || v > maxListLimit {
			writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
			return 0, 0, false
		}
		limit = v
	}

	offset = 0
	if raw := q.Get("offset"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 {
			writeError(w, http.StatusBadRequest, "offset must be a non-negative integer")
			return 0, 0, false
		}
		offset = v
	}

	return limit, offset, true
}

// handleCreateAttachment registers a resumable chunked upload for the device
// in the path. The body is strict JSON carrying the stable attachment id, the
// declared total size and chunk size (positive integers) and the lowercase
// hex SHA-256 of the final content. Any malformed input is a 400 JSON error
// and writes nothing; an unregistered device is a 404; an id already taken —
// by another device, or by this device with different metadata — is a 409
// that leaves the original record untouched.
func handleCreateAttachment(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty

	var req attachmentRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}

}

// writePollPage renders a long-poll result in the shared response shape: the
// ordinary page plus a timedOut flag, with the top-level keys in the fixed
// changes, nextCursor, timedOut order.
func writePollPage(w http.ResponseWriter, changes []events.ListedChange, nextCursor int64, timedOut bool) {
	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
		"timedOut":   timedOut,
	})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, map[string]string{"error": message})
}

// handlePollChanges is the long-polling entry over the change log.
//
// Query params share the existing change-read constraints: after is a
// non-negative cursor (default 0) and limit is 1..1000 (default 100); waitMs
// is 0..30000 (default 0). Rows already past after return immediately; a known
// document caught up to after parks until the first new commit or the wait
// deadline; an unknown document returns an empty page with cursor 0 at once.
// The response shape is the ordinary page plus a timedOut flag; a deadline
// expiry echoes the caller's cursor and never advances it. A client
// disconnect simply stops the wait and writes nothing.
func handlePollChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}
	waitMs, ok := parsePollWaitMs(w, r)
	if !ok {
		return
	}

	changes, nextCursor, timedOut, err := s.WaitForChanges(
		r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
	)
	switch {
	case errors.Is(err, events.ErrStoreClosing):
		writeError(w, http.StatusServiceUnavailable, "service is shutting down")
		return
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		// The client went away (or, with waitMs bounded, its deadline lapsed
		// at the transport): nothing more to write and nothing was stored.
		return
	case err != nil:
		writeError(w, http.StatusInternalServerError, "failed to poll changes")
		return
	}

package server

import (
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// handleDeleteDocument is the document-level data-cleanup entry:
//
//	DELETE /v1/documents/{documentID}?deviceId=D
//
// It removes one document's whole persisted data in a single serialized
// transaction. The calling device is declared by the deviceId query
// parameter — no new authentication is introduced and the call carries no
// body. The fixed verdict order is request shape (400, handled by routing and
// the empty-id guard) -> device existence (404) -> document permission (403)
// -> document existence (404); every failure writes nothing and cleans
// nothing. Success answers one compact JSON line naming the document id and
// the deletion marker and nothing else.
func handleDeleteDocument(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	deviceID := r.URL.Query().Get("deviceId")
	// A missing or empty deviceId is indistinguishable from an unregistered
	// caller; the gate also returns ErrDeviceNotFound for it, but judging here
	// keeps the 404 ahead of any document-content observation.
	if deviceID == "" {
		writeError(w, http.StatusNotFound, "device not found")
		return
	}

	if err := s.DeleteDocument(documentID, deviceID); err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.Is(err, events.ErrDocumentNotFound):
			writeError(w, http.StatusNotFound, "document not found")
		default:
			writeError(w, http.StatusInternalServerError, "failed to delete document")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"documentId": documentID, "deleted": true})
