29	// The session lookup answers in request order with a body byte-identical to
30	// the document-level lookup; the calling device is the session owner and a
31	// stray deviceId in the body is ignored.
32	func TestSessionQueryCRDTOpsHTTPSuccess(t *testing.T) {
33		h, _ := newTestHandler(t)
34		createSessionViaHTTP(t, h, "dev-1", "sess")
35		registerDevice(t, h, "dev-2")
36	
37		w, _ := postSessionCRDTOps(t, h, "sess", "doc", sessionCRDTBody("counter", crdtCounterOp("c1", 5)))
38		if w.Code != http.StatusOK {
39			t.Fatal(w.Body.String())
40		}
41		// A document-level batch from another device exercises device sourcing.
42		w, _ = postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtCounterBody("dev-2", crdtCounterOp("c2", 7)))
43		if w.Code != http.StatusOK {
44			t.Fatal(w.Body.String())
45		}
46	
47		// The stray deviceId is ignored: the session owner is the caller.
48		w = querySessionCRDTOps(t, h, "sess", "doc", `{"ids":["c2","c1","nope"],"deviceId":"someone-else"}`)
49		if w.Code != http.StatusOK {
50			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
51		}
52		want := `{"results":[` +
53			`{"id":"c2","status":"found","deviceId":"dev-2","value":7},` +
54			`{"id":"c1","status":"found","deviceId":"dev-1","value":5},` +
55			`{"id":"nope","status":"missing"}` +
56			`],"count":3}` + "\n"
57		if w.Body.String() != want {
58			t.Fatalf("body = %q\nwant %q", w.Body.String(), want)
59		}
60	}
61	
62	// The session lookup renders the same per-type shapes the document-level
63	// lookup renders.
64	func TestSessionQueryCRDTOpsHTTPAllTypes(t *testing.T) {
65		h, _ := newTestHandler(t)
